SELECT comment_id, post_id, user_id, content, created_at
FROM comments
WHERE comment_id = #{commentId}

SELECT comment_id, post_id, user_id, content, created_at
FROM comments
WHERE post_id = #{postId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT comment_id, post_id, user_id, content, created_at
FROM comments
WHERE user_id = #{userId}
ORDER BY created_at DESC
LIMIT #{limit} OFFSET #{offset}
